  ["cd349e646ebc2671"] = { "Inserimento della scheda di sicurezza gialla riuscito. Erogazione dell'unità chi di livello di sicurezza.\n\n01010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001", "." },
  ["cd3a2af5e14a4a58"] = { "Sempre in movimento, quella ragazza.", "." },
